create or replace function public.business_location_detail(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ select coalesce(jsonb_agg(to_jsonb(x) order by x.check_ins desc,x.name),'[]'::jsonb) from (select l.id,l.name,l.address,l.city,l.state,l.is_active,l.rating,l.review_count,count(distinct ci.id) filter(where ci.checked_in_at between p_start and p_end) check_ins,count(distinct ci.user_id) filter(where ci.checked_in_at between p_start and p_end) unique_visitors,count(distinct r.id) filter(where r.created_at between p_start and p_end and r.status<>'hidden') reviews from locations l left join check_ins ci on ci.location_id=l.id left join reviews r on r.location_id=l.id where l.business_id=p_business_id group by l.id) x; $$;
create or replace function public.business_qr_detail(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ select coalesce(jsonb_agg(to_jsonb(x) order by x.check_ins desc,x.label),'[]'::jsonb) from (select q.id,q.label,q.active,l.name location,count(ci.id) filter(where ci.checked_in_at between p_start and p_end) check_ins,count(distinct ci.user_id) filter(where ci.checked_in_at between p_start and p_end) unique_users,max(ci.checked_in_at) last_check_in from qr_codes q join locations l on l.id=q.location_id left join check_ins ci on ci.qr_code_id=q.id where l.business_id=p_business_id group by q.id,q.label,q.active,l.name) x; $$;
create or replace function public.business_review_detail(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from (select r.id,l.name location,r.stars,r.cleanliness_pct,r.comment,r.status,r.business_reply,r.created_at from reviews r join locations l on l.id=r.location_id where l.business_id=p_business_id and r.created_at between p_start and p_end) x; $$;
create or replace function public.business_media_detail(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from (select p.id,l.name location,p.media_type,p.mime_type,p.size_bytes,p.width,p.height,p.caption,p.storage_path,p.created_at from location_photos p join locations l on l.id=p.location_id where l.business_id=p_business_id and p.created_at between p_start and p_end) x; $$;
create or replace function public.business_promotion_detail(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from (select p.id,p.title,p.description,p.discount,p.active,p.starts_at,p.ends_at,p.created_at,l.name location,count(ae.id) filter(where ae.event_type='promotion_view' and ae.created_at between p_start and p_end) views,count(ae.id) filter(where ae.event_type='promotion_redeemed' and ae.created_at between p_start and p_end) redemptions from promotions p left join locations l on l.id=p.location_id left join analytics_events ae on ae.promotion_id=p.id where p.business_id=p_business_id group by p.id,p.title,p.description,p.discount,p.active,p.starts_at,p.ends_at,p.created_at,l.name) x; $$;
create or replace function public.business_partner_detail(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from (select p.id,p.name,p.enabled,p.preferred_access,p.match_discount_bonus,p.custom_perk,p.created_at,count(pa.id) agreements,count(pa.id) filter(where pa.status='active') active_agreements from partner_programs p left join partner_agreements pa on pa.partner_program_id=p.id where p.business_id=p_business_id group by p.id,p.name,p.enabled,p.preferred_access,p.match_discount_bonus,p.custom_perk,p.created_at) x; $$;
create or replace function public.business_event_detail(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ select coalesce(jsonb_agg(to_jsonb(x) order by x.event_date desc,x.created_at desc),'[]'::jsonb) from (select e.id,e.title,e.description,e.event_date,e.event_time,e.created_at,l.name location,count(er.user_id) rsvps from business_events e left join locations l on l.id=e.location_id left join event_rsvps er on er.event_id=e.id where e.business_id=p_business_id and(e.event_date is null or e.event_date between p_start::date and p_end::date) group by e.id,e.title,e.description,e.event_date,e.event_time,e.created_at,l.name) x; $$;
create or replace function public.business_campaign_detail(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from (select c.id,c.name,c.campaign_type,c.goal,c.status,c.created_at,coalesce(sum(o.visits) filter(where o.metric_date between p_start::date and p_end::date),0) visits,coalesce(sum(o.check_ins) filter(where o.metric_date between p_start::date and p_end::date),0) check_ins,coalesce(sum(o.reviews) filter(where o.metric_date between p_start::date and p_end::date),0) reviews,coalesce(sum(o.attributed_users) filter(where o.metric_date between p_start::date and p_end::date),0) attributed_users from enterprise_partner_campaigns c left join enterprise_partner_campaign_outcomes o on o.campaign_id=c.id where c.network_id in(select id from enterprise_partner_networks where owner_business_id=p_business_id) group by c.id,c.name,c.campaign_type,c.goal,c.status,c.created_at) x; $$;
